// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Agents read projects over MCP"
// Changes: The read tools of the agent interface (find, analyse, simulate). They never write: simulations take their
//          input as an argument and leave the project's revision and saved simulation inputs alone.

import { TEXT_EXPORT_KINDS, analyzeProject, type TextExportKind } from '#/lib/projectAnalysis'
import { ruleText } from '#/lib/grammar'
import { PARTS, readPart, type PartName } from '#/lib/parts'
import { precTable } from '#/lib/precedence'
import type { ProjectData } from '#/lib/project'
import { z } from 'zod'
import { resolveTarget, targetSchema } from './targets.server'
import { READ_ONLY, ToolError, defineTool, type AgentTool } from './tools.server'

const partSchema = z
  .enum(PARTS)
  .describe('definition (N, T, S), grammarRules (P, one rule per line), precTable (precedence terminals and relations), reductionRules')

/** A part as agents see it: texts as they are; the precedence table as its terminals and the set relations in grid order. */
function partValue(data: ProjectData, part: PartName) {
  if (part !== 'precTable') return readPart(data, part)
  const table = precTable(data.prec)
  return {
    terminals: table.columns.filter((t) => t !== '$'),
    relations: table.rows.flatMap((row) =>
      row.relations.flatMap((relation, i) => (relation ? [{ stack: row.terminal, input: table.columns[i], relation }] : [])),
    ),
  }
}

const listProjects = defineTool({
  name: 'list_projects',
  description:
    'Lists every project (most recently updated first) with its id, name, revision and creation/update times. ' +
    'Use the id as {"kind":"project","id":…} in the target of other tools.',
  input: {},
  annotations: READ_ONLY,
  run: (_args, { store }) => ({
    projects: store.listProjects().map((p) => ({ id: p.id, name: p.name, revision: p.revision, createdAt: p.createdAt, updatedAt: p.updatedAt })),
  }),
})

const listSnapshots = defineTool({
  name: 'list_snapshots',
  description:
    'Lists the snapshots (earlier versions, newest first) of a project: id, label, kind (auto: periodic backup while ' +
    'editing; named: saved by the human; safety: taken before a restore or import) and creation time. ' +
    'Read one with {"kind":"snapshot","id":<id>} as the target of the other read tools.',
  input: { target: targetSchema.describe('The project whose snapshots to list: {"kind":"project","id":"<project id>"}') },
  annotations: READ_ONLY,
  run: ({ target }, { store }) => {
    const t = resolveTarget(store, target)
    if (!t.listSnapshots) throw new ToolError(`A ${t.ref.kind} has no snapshots of its own; pass its project as the target.`)
    return { target: t.ref, snapshots: t.listSnapshots().map(({ id, label, kind, createdAt }) => ({ id, label, kind, createdAt })) }
  },
})

const getPart = defineTool({
  name: 'get_part',
  description:
    'Reads one part of a target. definition: {nonterminals, terminals, start} as the human typed them (one symbol per line, optional note). ' +
    'grammarRules / reductionRules: the rules text, one rule per line. precTable: {terminals (without $), relations: ' +
    '[{stack, input, relation}]} listing only the set relations (<, =, >) by stack terminal (row) and input terminal (column).',
  input: { target: targetSchema, part: partSchema },
  annotations: READ_ONLY,
  run: ({ target, part }, { store }) => {
    const t = resolveTarget(store, target)
    return { target: t.ref, part, value: partValue(t.data, part) }
  },
})

const getProjectSettings = defineTool({
  name: 'get_project_settings',
  description:
    "Reads the project's export naming (symbol name map and C prefixes for nonterminals, terminals and precedence " +
    'terminals) and its saved simulation inputs. These belong to the project, not to its parts: a snapshot target ' +
    'shows its project\'s current settings. Read-only – only the human changes them; to simulate another input pass it to simulate_ll / simulate_prec.',
  input: { target: targetSchema },
  annotations: READ_ONLY,
  run: ({ target }, { store }) => {
    const { ref, data } = resolveTarget(store, target)
    return {
      target: ref,
      exportNaming: {
        symbolNames: data.names.map,
        nonterminalPrefix: data.names.ntPrefix,
        terminalPrefix: data.names.tPrefix,
        precedenceTerminalPrefix: data.names.precPrefix,
      },
      simulationInputs: { ll: data.ll.input, prec: data.prec.input },
    }
  },
})

const getLLTable = defineTool({
  name: 'get_ll_table',
  description:
    'Gets the LL(1) table computed from the definition and grammar rules of a target. Rules are numbered 1.. in the ' +
    'order of the grammar rules; rows are nonterminals and list only non-empty cells as {terminal, rules: [rule numbers], ' +
    'conflict}; columns are the terminals with the end marker last. A cell with more than one rule is an LL(1) conflict; ' +
    'all of them are also listed in conflicts. The table is never edited directly – it changes only with the grammar rules or definition.',
  input: { target: targetSchema },
  annotations: READ_ONLY,
  run: ({ target }, { store }) => {
    const { ref, data } = resolveTarget(store, target)
    const a = analyzeProject(data).grammar.ll
    if (!a) return { target: ref, rules: [], columns: [], rows: [], conflicts: [] }
    const rows = a.N.map((nonterminal) => ({
      nonterminal,
      cells: a.cols.flatMap((terminal) => {
        const rules = a.table.get(nonterminal)?.get(terminal) ?? []
        return rules.length ? [{ terminal, rules: [...rules], conflict: rules.length > 1 }] : []
      }),
    }))
    return {
      target: ref,
      rules: a.rules.map((r, i) => ({ rule: i + 1, text: ruleText(r) })),
      columns: [...a.cols],
      rows,
      conflicts: rows.flatMap((row) =>
        row.cells.filter((c) => c.conflict).map((c) => ({ nonterminal: row.nonterminal, terminal: c.terminal, rules: c.rules })),
      ),
    }
  },
})

const getSets = defineTool({
  name: 'get_sets',
  description:
    'Gets the LL sets of a target: per nonterminal whether it derives ε (empty) and its First and Follow sets; per ' +
    'grammar rule (numbered 1.. like in get_ll_table) its Predict set. A terminal in the Predict sets of two rules of ' +
    'the same nonterminal is what makes an LL(1) conflict. Empty lists without grammar rules.',
  input: { target: targetSchema },
  annotations: READ_ONLY,
  run: ({ target }, { store }) => {
    const { ref, data } = resolveTarget(store, target)
    return { target: ref, ...(analyzeProject(data).sets ?? { nonterminals: [], predict: [] }) }
  },
})

const getPrecTable = defineTool({
  name: 'get_prec_table',
  description:
    'Gets the precedence table of a target as the full grid: columns are the precedence terminals with $ last (the ' +
    'same list labels the rows); each row is the terminal on top of the stack and its relations against each input ' +
    "column in column order: '<', '=', '>' or '' for an empty cell. Use get_part with part precTable for just the set relations.",
  input: { target: targetSchema },
  annotations: READ_ONLY,
  run: ({ target }, { store }) => {
    const { ref, data } = resolveTarget(store, target)
    return { target: ref, ...analyzeProject(data).precTable }
  },
})

const getProblems = defineTool({
  name: 'get_problems',
  description:
    'Gets the problems the app reports for a target, grouped as definition (declared N, T, S vs. the grammar rules), ' +
    "ll (grammar errors, LL(1) conflicts) and prec (precedence table and reduction rules). Each problem is {level, text}; level 'bad' " +
    "is an error, 'warn' a warning, 'ok' a passed check and 'info' a note. Texts are in Slovak, as the human sees them.",
  input: { target: targetSchema },
  annotations: READ_ONLY,
  run: ({ target }, { store }) => {
    const { ref, data } = resolveTarget(store, target)
    return { target: ref, problems: analyzeProject(data).problems }
  },
})

const exportTarget = defineTool({
  name: 'export',
  description:
    'Produces a text export of a target, ready to paste: def-md / def-tex (the formal definition G = (N, T, P, S)), ' +
    'll-md, ll-sets-md, ll-csv, ll-tex, ll-c (LL table, sets) and prec-md, prec-csv, prec-tex, prec-c (precedence table). ' +
    "C exports use the project's export naming. Returns {kind, fileName, mediaType, text}; a tool error when the target " +
    'has nothing to export (e.g. no grammar rules or no precedence terminals). PNG exports are not available here.',
  input: {
    target: targetSchema,
    kind: z.enum(TEXT_EXPORT_KINDS as [TextExportKind, ...TextExportKind[]]).describe('Export kind'),
  },
  annotations: READ_ONLY,
  run: ({ target, kind }, { store }) => {
    const { ref, data } = resolveTarget(store, target)
    const result = analyzeProject(data).export(kind)
    if (result.type === 'error') throw new ToolError(`Cannot export ${kind}: ${result.error}`)
    return { target: ref, kind, fileName: result.name, mediaType: result.mime, text: result.text }
  },
})

const simulationInput = z
  .string()
  .max(10_000)
  .describe('Input symbols separated by spaces (terminals as in the rules, e.g. "id + id"); the end marker is added automatically')

function requireInput(input: string) {
  if (!input.trim()) throw new ToolError('The input is empty; pass the symbols to parse, separated by spaces.')
}

const simulateLLTool = defineTool({
  name: 'simulate_ll',
  description:
    'Runs the LL(1) parse of a target on the given input and returns the full trace: one step per row with the stack ' +
    "(top on the right), the remaining input, the kind (expand by a rule, match a terminal, accept, error), the action " +
    'text and, for expansions, the rule number and the LL table cell used. ok and message tell the outcome (message in ' +
    'Slovak); leftParse lists the applied rule numbers. Pure: it never changes the target or the saved simulation input. ' +
    'On a conflicting cell the first rule is used.',
  input: { target: targetSchema, input: simulationInput },
  annotations: READ_ONLY,
  run: ({ target, input }, { store }) => {
    requireInput(input)
    const { ref, data } = resolveTarget(store, target)
    const sim = analyzeProject(data).simulateLL(input)
    if (!sim) throw new ToolError('The target has no grammar rules to simulate.')
    return {
      target: ref,
      input,
      ok: sim.ok,
      message: sim.message,
      leftParse: sim.rows.flatMap((row) => (row.kind === 'expand' && row.rule ? [row.rule] : [])),
      steps: sim.rows.map((row) => ({
        stack: row.stack,
        input: row.input,
        kind: row.kind,
        action: row.action,
        ...(row.rule !== undefined && { rule: row.rule }),
        ...(row.cell && { cell: { nonterminal: row.cell[0], terminal: row.cell[1] } }),
      })),
    }
  },
})

const simulatePrecTool = defineTool({
  name: 'simulate_prec',
  description:
    'Runs the operator-precedence parse of a target on the given input, reducing handles by the reduction rules, and ' +
    'returns the full trace: one step per row with the stack (bottom $ first, < marks a handle start), the relation looked ' +
    "up between the topmost stack terminal and the next input symbol ('<', '=', '>' or '' when the cell is empty), the " +
    'remaining input and the reduction rule applied (empty when none). ok and message tell the outcome (message in ' +
    'Slovak). Pure: it never changes the target or the saved simulation input.',
  input: { target: targetSchema, input: simulationInput },
  annotations: READ_ONLY,
  run: ({ target, input }, { store }) => {
    requireInput(input)
    const { ref, data } = resolveTarget(store, target)
    const sim = analyzeProject(data).simulatePrec(input)
    if (!sim) throw new ToolError('The target has no reduction rules to simulate.')
    return {
      target: ref,
      input,
      ok: sim.ok,
      message: sim.message,
      steps: sim.rows.map((row) => ({
        stack: row.stack.map((item) => item.s).join(' '),
        relation: row.op,
        input: row.input,
        rule: row.rule,
      })),
    }
  },
})

export const READ_TOOLS: readonly AgentTool[] = [listProjects, listSnapshots, getPart, getProjectSettings, getLLTable, getSets, getPrecTable, getProblems, exportTarget, simulateLLTool, simulatePrecTool]
